        var document=await Document(a1);
        async Task<Guid> Event(LifecycleEventInput input,bool approve=true){var id=await owner.ProposeLifecycleEventAsync(account,a1,input,Guid.NewGuid());if(approve){var e=(await Details(a1)).Events.Single(x=>x.Id==id);await admin.DecideLifecycleEventAsync(account,id,e.Revision,true,"Checked source",Guid.NewGuid());}return id;}
        var partial=await Event(new(){Kind=LeasingLifecycleKind.Return,Date=new(2028,1,16),ItemId=item,Quantity=1,Reason="Partial untracked return"});
        Check((await Details(a1)).Dispositions.Where(x=>!x.Reversed).Sum(x=>x.Quantity)==1,"partial return without serial tracking records line quantity");
        var invalid=await Event(new(){Kind=LeasingLifecycleKind.Return,Date=new(2028,1,16),ItemId=item,Quantity=2,Reason="Must select tracked units"},false);var invalidEvent=(await Details(a1)).Events.Single(x=>x.Id==invalid);await Reject(()=>admin.DecideLifecycleEventAsync(account,invalid,invalidEvent.Revision,true,"Invalid",Guid.NewGuid()),"LifeSelectUnits");
        var swap=await Event(new(){Kind=LeasingLifecycleKind.Replace,Date=new(2028,1,16),ItemId=item,EquipmentIds=[units[0]],Quantity=1,ReplacementEquipmentId=replacement,Reason="Registered replacement",SourceDocumentId=document});Check((await Details(a1)).Equipment.Single(x=>x.Id==units[0]).ReplacementEquipmentId==replacement,"replacement links existing purchased unit without new purchase effects");
        var returned=await Event(new(){Kind=LeasingLifecycleKind.Return,Date=new(2028,1,16),ItemId=item,EquipmentIds=[units[1]],Quantity=1,Reason="Tracked return"});var returnedEvent=(await Details(a1)).Events.Single(x=>x.Id==returned);await admin.ReverseLifecycleEventAsync(account,returned,returnedEvent.Revision,"Wrong unit",Guid.NewGuid());Check((await Details(a1)).Equipment.Single(x=>x.Id==units[1]).Status==LeasingEquipmentStatus.InUse&&(await Details(a1)).Dispositions.Any(x=>x.EventId==returned&&x.Reversed),"traceable latest-event reversal restores physical status and preserves history");
        await Event(new(){Kind=LeasingLifecycleKind.Buyout,Date=new(2028,1,16),ItemId=item,EquipmentIds=[units[1]],Quantity=1,BuyoutAmount=75,SourceDocumentId=document,Reason="Actual agreed buyout price"});
        await Event(new(){Kind=LeasingLifecycleKind.Return,Date=new(2028,1,16),ItemId=item,Quantity=1,Reason="Remaining untracked return"});Check((await Details(a1)).Dispositions.Where(x=>!x.Reversed).Sum(x=>x.Quantity)==4,"tracked and untracked dispositions share a single quantity ceiling");
        await Reject(()=>admin.SaveEquipmentAsync(account,a1,[Unit(item,"S4","ASSET-4")],false,"Over line quantity",Guid.NewGuid()),"LifeOverQuantity");
        var extension=await Event(new(){Kind=LeasingLifecycleKind.Extend,Date=new(2028,1,16),PreviousEndDate=new(2028,1,1),NewEndDate=new(2029,1,1),TermsReference="Continued terms with revised rent",PaymentsChanged=true,SourceDocumentId=document,Reason="Confirmed extension"});var extended=await Details(a1);Check(extended.Lifecycle.AgreedEndDate==new DateOnly(2029,1,1)&&extended.Lifecycle.OriginalEndDate==new DateOnly(2028,1,1)&&extended.Acquisition.EndDate==new DateOnly(2028,1,1)&&extended.Lifecycle.PaymentPlanReviewRequired,"extension preserves original dates and flags payment plan without calculating new amounts");
