        var term=new LeasingPlanTerm{Reference="EXT-1",PeriodFrom=new(2028,2,1),PeriodTo=new(2028,2,29),DueDate=new(2028,3,5),Net=100,Vat=25,Gross=125,ReviewReason="Extension documented"};var plan=await owner.SavePaymentPlanAsync(account,a1,null,[term],"Extension",LeasingPlanSource.Manual,document,Guid.NewGuid());var p=(await admin.GetPaymentsAsync(account,a1)).Plans.Single();await admin.ActivatePaymentPlanAsync(account,plan,p.Revision,"Check extension period",false,Guid.NewGuid());extended=await Details(a1);await admin.ReviewLifecycleDocumentsAsync(account,a1,extended.Lifecycle.Revision,true,true,"Revised plan activated",Guid.NewGuid());
        var revisedTerm=JsonSerializer.Deserialize<LeasingPlanTerm>(JsonSerializer.Serialize((await admin.GetPaymentsAsync(account,a1)).Terms.Single().Term))!;revisedTerm.Net=110;revisedTerm.Vat=27.5m;revisedTerm.Gross=137.5m;var newPlan=await owner.SavePaymentPlanAsync(account,a1,plan,[revisedTerm],"Updated plan",LeasingPlanSource.Manual,document,Guid.NewGuid());p=(await admin.GetPaymentsAsync(account,a1)).Plans.Single(x=>x.Id==newPlan);await admin.ActivatePaymentPlanAsync(account,newPlan,p.Revision,"Activate revision",false,Guid.NewGuid());
        var closing=await Event(new(){Kind=LeasingLifecycleKind.EarlyClose,Date=new(2028,1,16),SourceDocumentId=document,Reason="Early return agreement",UnresolvedConfirmed=false},false);var ce=(await Details(a1)).Events.Single(x=>x.Id==closing);await Reject(()=>admin.DecideLifecycleEventAsync(account,closing,ce.Revision,true,"Open invoices",Guid.NewGuid()),"LifeConfirmUnresolved");
        await Event(new(){Kind=LeasingLifecycleKind.EarlyClose,Date=new(2028,1,16),SourceDocumentId=document,Reason="Final invoices to follow",UnresolvedConfirmed=true});Check((await Details(a1)).Lifecycle.Status==LeasingLifecycleStatus.Closed&&(await Details(a1)).Acquisition.Status==LeasingAcquisitionStatus.Registered&&(await admin.GetPaymentsAsync(account,a1)).Terms.Single().Term.Gross==137.5m,"early closure keeps financial registration and future plan terms");
        var invoice=await owner.NewRentalInvoiceAsync(account,Guid.NewGuid());var ir=await owner.GetRentalInvoiceAsync(account,invoice);ir.Review.FinanceOrganizationId=party;ir.Review.Data=new(){Number="FINAL",Date=new(2028,1,16),Currency="NOK",Net=110,Vat=27.5m,Gross=137.5m,Lines=[new(){SourceId="1",Description="Final rent",Quantity=1,Price=110,Net=110,VatPercent=25,VatCategory="S"}]};ir.Review.ContentConfirmed=true;ir.Review.Allocations=[new(){InstallmentId=(await admin.GetPaymentsAsync(account,a1)).Terms.Single().Installment.Id,Net=100,Vat=25}];await owner.SaveRentalReviewAsync(account,invoice,ir.Invoice.Revision,ir.Review);ir=await admin.GetRentalInvoiceAsync(account,invoice);await admin.ApproveRentalInvoiceAsync(account,invoice,ir.Invoice.Revision);Check((await admin.GetPaymentsAsync(account,a1)).Terms.Single().InvoicedNet==100,"final invoices remain possible after lifecycle closure");
        var after=await admin.GetAsync(account,frame,true);Check(after.Used==before.Used&&after.Reserved==before.Reserved&&(await Details(a1)).Acquisition.FinancedAmount==750,"lifecycle events preserve purchase value, capacity, reservation and financing");
        var capacity=await admin.GetLeasingReportAsync(account,LeasingReportKind.Capacity,new());Check(capacity.Totals.Single(x=>x.Currency=="NOK").Used==after.Used&&capacity.Totals.Single().Reserved==after.Reserved,"capacity report uses shared live control calculations");
        var dimension=Guid.NewGuid();var tag1=Guid.NewGuid();var tag2=Guid.NewGuid();
        await using(var db=factory.CreateDbContext())
        {
            db.Dimensions.Add(new(){Id=dimension,AccountId=account,Name="Tags now renamed",Code="TAGS",AllowMultiple=true,Revision=Guid.NewGuid()});
            db.DimensionValues.AddRange(new TenantPlatform.Core.Dimensions.DimensionValue{Id=tag1,AccountId=account,DimensionId=dimension,Name="Current first",Code="A",Revision=Guid.NewGuid()},new TenantPlatform.Core.Dimensions.DimensionValue{Id=tag2,AccountId=account,DimensionId=dimension,Name="Current second",Code="B",Revision=Guid.NewGuid()});
            foreach(var tag in new[]{tag1,tag2})db.LeasingDimensionSelections.Add(new(){Id=Guid.NewGuid(),AccountId=account,ItemId=replacementItem,DimensionId=dimension,ValueId=tag,DimensionName="Original tag name",DimensionCode="TAGS",ValueName="Historical label",ValueCode=tag==tag1?"A":"B",ValuePath="Historical label"});await db.SaveChangesAsync();
        }
        var dimensions=await admin.GetLeasingReportAsync(account,LeasingReportKind.Dimensions,new(){DimensionValueId=tag1});
        Check(dimensions.Count==1&&dimensions.Totals.Single().Gross==1250&&dimensions.Rows.Single().Dimensions.Contains("Original tag name"),"multiple classification tags filter without multiplying money and retain historical names");
        var splitDimension=Guid.NewGuid();var splitValue1=Guid.NewGuid();var splitValue2=Guid.NewGuid();var splitRow1=Guid.NewGuid();var splitRow2=Guid.NewGuid();
        await using(var db=factory.CreateDbContext())
        {
            db.Dimensions.Add(new(){Id=splitDimension,AccountId=account,Name="Department",Code="DEPT",Revision=Guid.NewGuid()});
            foreach(var v in new[]{splitValue1,splitValue2})db.DimensionValues.Add(new(){Id=v,AccountId=account,DimensionId=splitDimension,Name=v.ToString(),Code=v.ToString(),Revision=Guid.NewGuid()});
            var line=await db.LeasingItems.SingleAsync(x=>x.AccountId==account&&x.Id==item);line.AllocationMode=LeasingAllocationMode.Percent;
            db.LeasingAllocationDimensions.Add(new(){AccountId=account,ItemId=item,DimensionId=splitDimension,DimensionName="Historic department",DimensionCode="DEPT"});
