            foreach(var pair in new[]{(splitRow1,splitValue1),(splitRow2,splitValue2)})db.LeasingDimensionSelections.Add(new(){Id=Guid.NewGuid(),AccountId=account,ItemId=item,AllocationRowId=pair.Item1,DimensionId=splitDimension,ValueId=pair.Item2,DimensionName="Historic department",DimensionCode="DEPT",ValueName="Historic value",ValueCode="V",ValuePath="Historic value"});await db.SaveChangesAsync();
        }
        var splitReport=await admin.GetLeasingReportAsync(account,LeasingReportKind.Dimensions,new(){DimensionValueId=splitValue1});Check(splitReport.Count==1&&splitReport.Totals.Single().Gross==312.5m,"dimension report uses actual financial allocation rows exactly once");
        var payments=await admin.GetLeasingReportAsync(account,LeasingReportKind.Payments,new());Check(payments.Totals.Single(x=>x.Currency=="NOK").Expected==137.5m,"planned report uses only active versions without replaced-plan double counting");Check(payments.Totals.Select(x=>x.Currency).Order().SequenceEqual(new[]{"EUR","NOK"}),"report totals keep currencies separate and flag missing plans");
        var invoices=await admin.GetLeasingReportAsync(account,LeasingReportKind.InvoiceControl,new());Check(invoices.Totals.Single(x=>x.Currency=="NOK").Invoiced==125&&invoices.Totals.Single(x=>x.Currency=="NOK").Unallocated==12.5m,"invoice report separates allocated totals and document remainder exactly once");
        var dateFilter=new LeasingReportFilter{DateField=LeasingReportDate.Invoice,From=new(2028,1,16),To=new(2028,1,16)};Check((await admin.GetLeasingReportAsync(account,LeasingReportKind.InvoiceControl,dateFilter)).Totals.Single().Invoiced==125,"invoice-date filtering retains matching allocations");
        Check((await outsider.GetLeasingReportAsync(account,LeasingReportKind.Agreements,new())).Count==0,"ordinary unrelated member sees no report rows");await Deny(()=>owner.GetLeasingReportAsync(account,LeasingReportKind.Payments,new(),export:true));await Deny(()=>admin.GetLeasingReportAsync(foreignAccount,LeasingReportKind.Capacity,new(),export:true));
        var dashboard=await admin.GetLeasingDashboardAsync(account,new(2028,1,1),new(2028,12,31));Check(dashboard.Reports[LeasingReportKind.Capacity].Totals.Single().Used==capacity.Totals.Single().Used&&dashboard.Reports[LeasingReportKind.Payments].Totals.Single().Expected==137.5m,"dashboard amounts equal drill-down reports");
