    sealed class MutableClock:TimeProvider{public DateTimeOffset Now{get;set;}public override DateTimeOffset GetUtcNow()=>Now;}
    static void Check(bool ok,string message){if(!ok)throw new Exception("FAIL lifecycle: "+message);Console.WriteLine("PASS lifecycle: "+message);}
    static async Task Reject(Func<Task> action,string key){try{await action();throw new Exception("Expected "+key);}catch(LeasingValidationException e)when(e.Message==key){Console.WriteLine("PASS lifecycle rejection: "+key);}}
    static async Task Deny(Func<Task> action){try{await action();throw new Exception("Expected denial");}catch(UnauthorizedAccessException){Console.WriteLine("PASS lifecycle access denied");}}
}
